ROtapRuntime.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

/// Independent NAND/LATCH runtime, based on the published wire format.
/// REF execution is deliberately rejected until its full state semantics are verified.
library ROtapRuntime {
    struct Metrics {uint32 nand;uint32 latch;uint32 depth;uint256 burn;uint256 area;uint256 cost;}
    function u24(bytes memory data,uint256 offset) internal pure returns(uint256){
        require(offset+3<=data.length,"TRUNCATED");
        return (uint256(uint8(data[offset]))<<16)|(uint256(uint8(data[offset+1]))<<8)|uint8(data[offset+2]);
    }
    function counts(bytes memory data) internal pure returns(uint32 nand,uint32 latch){
        uint256 pos;
        while(pos<data.length){uint8 op=uint8(data[pos]);uint256 size;
            if(op==0){nand++;size=7;}else if(op==1){latch++;size=4;}else revert("UNSUPPORTED_OPCODE");
            require(pos+size<=data.length,"TRUNCATED");pos+=size;
        }
    }
    function inspect(bytes memory data,uint32 nIn,uint32 nOut) internal pure returns(Metrics memory m){
        (m.nand,m.latch)=counts(data);uint256 length=2+uint256(nIn)+m.nand+m.latch;
        require(nOut>0&&nOut<=length,"OUTPUTS");
        uint256[] memory levels=new uint256[](length);
        uint256[] memory nextState=new uint256[](m.latch);
        uint256 wire=2+uint256(nIn);uint256 pos;uint256 stateId;
        while(pos<data.length){uint8 op=uint8(data[pos++]);uint256 a=u24(data,pos);
            if(op==0){uint256 b=u24(data,pos+3);require(a<wire&&b<wire,"FORWARD_NAND");levels[wire]=1+(levels[a]>levels[b]?levels[a]:levels[b]);pos+=6;}
            else {require(a<length,"STATE_WIRE");nextState[stateId++]=a;pos+=3;}
            wire++;
        }
        uint256 depth;
        for(uint256 i=length-nOut;i<length;i++)if(levels[i]>depth)depth=levels[i];
        for(uint256 i;i<nextState.length;i++)if(levels[nextState[i]]>depth)depth=levels[nextState[i]];
        m.depth=uint32(depth);m.burn=uint256(m.nand)+m.latch;
        m.area=uint256(m.nand)+uint256(m.latch)*7;
        m.cost=m.area*(depth==0?1:depth)**3;
    }
    function bit(bytes memory data,uint256 index) internal pure returns(bool){
        return index/8<data.length&&(uint8(data[index/8])&(uint8(1)<<uint8(index%8)))!=0;
    }
    function setBit(bytes memory data,uint256 index) internal pure {data[index/8]|=bytes1(uint8(1)<<uint8(index%8));}
    function liveGateCount(bytes memory data,uint32 nIn,uint32 nOut) internal pure returns(uint32 count){
        Metrics memory measured=inspect(data,nIn,nOut);uint256 gates=uint256(measured.nand)+measured.latch;uint256 base=2+uint256(nIn);
        uint256[] memory a=new uint256[](gates);uint256[] memory b=new uint256[](gates);bool[] memory nand=new bool[](gates);
        uint256 pos;uint256 gate;
        while(pos<data.length){uint8 op=uint8(data[pos++]);a[gate]=u24(data,pos);if(op==0){nand[gate]=true;b[gate]=u24(data,pos+3);pos+=6;}else pos+=3;gate++;}
        bool[] memory queued=new bool[](gates);uint256[] memory stack=new uint256[](gates);uint256 size;
        for(uint256 wire=base+gates-nOut;wire<base+gates;wire++)if(wire>=base){uint256 index=wire-base;queued[index]=true;stack[size++]=index;}
        while(size>0){uint256 index=stack[--size];count++;uint256 first=a[index];if(first>=base&&!queued[first-base]){queued[first-base]=true;stack[size++]=first-base;}
            if(nand[index]){uint256 second=b[index];if(second>=base&&!queued[second-base]){queued[second-base]=true;stack[size++]=second-base;}}
        }
    }
    function run(bytes memory data,uint32 nIn,uint32 nOut,bytes memory state,bytes memory inputs) internal pure returns(bytes memory newState,bytes memory outputs){
        Metrics memory m=inspect(data,nIn,nOut);
        require(inputs.length==(uint256(nIn)+7)/8,"INPUT_LENGTH");
        require(state.length==0||state.length==(uint256(m.latch)+7)/8,"STATE_LENGTH");
        bool[] memory wires=new bool[](2+uint256(nIn)+m.nand+m.latch);wires[1]=true;
        for(uint256 i;i<nIn;i++)wires[2+i]=bit(inputs,i);
        uint256[] memory updateFrom=new uint256[](m.latch);
        uint256 pos;uint256 at=2+uint256(nIn);uint256 stateId;
        while(pos<data.length){uint8 op=uint8(data[pos++]);uint256 a=u24(data,pos);
            if(op==0){wires[at]=!(wires[a]&&wires[u24(data,pos+3)]);pos+=6;}
            else {updateFrom[stateId]=a;wires[at]=bit(state,stateId++);pos+=3;}at++;
        }
        newState=new bytes((uint256(m.latch)+7)/8);outputs=new bytes((uint256(nOut)+7)/8);
        for(uint256 i;i<m.latch;i++)if(wires[updateFrom[i]])setBit(newState,i);
        for(uint256 i;i<nOut;i++)if(wires[wires.length-nOut+i])setBit(outputs,i);
    }
}

contract ROtapRuntimeHarness {
    function metrics(bytes calldata data,uint32 nIn,uint32 nOut) external pure returns(ROtapRuntime.Metrics memory){return ROtapRuntime.inspect(data,nIn,nOut);}
    function step(bytes calldata data,uint32 nIn,uint32 nOut,bytes calldata state,bytes calldata inputs) external pure returns(bytes memory,bytes memory){return ROtapRuntime.run(data,nIn,nOut,state,inputs);}
    function liveGates(bytes calldata data,uint32 nIn,uint32 nOut) external pure returns(uint32){return ROtapRuntime.liveGateCount(data,nIn,nOut);}
}

ROtapTransistors.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

// Independent implementation candidate. Full Fab X equivalence remains unverified.
contract ROtapTransistors {
    uint256 public constant NAND=0;
    uint256 public constant LATCH=1;
    uint256 public supplyCap;
    uint256 public mintPrice;
    uint256 public protocolFee;
    address public creator;
    address public protocolWallet;
    address public circuits;
    string public cpuName;
    string public cpuSymbol;
    string public story;
    uint256 public walletCap;
    mapping(uint256=>uint256) public typeCap;
    bool private initialized;
    uint256 public minted;
    mapping(uint256=>uint256) public mintedOf;
    mapping(address=>uint256) public mintedBy;
    mapping(address=>uint256) public owed;
    mapping(uint256=>mapping(address=>uint256)) private balances;
    mapping(address=>mapping(address=>bool)) public isApprovedForAll;
    uint256 private entered;
    event TransferSingle(address indexed operator,address indexed from,address indexed to,uint256 id,uint256 value);
    event TransferBatch(address indexed operator,address indexed from,address indexed to,uint256[] ids,uint256[] values);
    event ApprovalForAll(address indexed account,address indexed operator,bool approved);
    event PricingSet(uint256 price,uint256 fee,uint256 cap);
    event TypeCapsSet(uint256 nandCap,uint256 latchCap);
    event WalletCapSet(uint256 cap);
    modifier nonReentrant(){require(entered==0,"REENTRANCY");entered=1;_;entered=0;}
    constructor(address creator_,address protocolWallet_,address circuits_,uint256 price_,uint256 fee_){
        initialized=true;
        if(creator_!=address(0))_initialize('ROtap','ROTAP','',creator_,1_000_000,price_,protocolWallet_,fee_,circuits_);
    }
    function initialize(string calldata name_,string calldata symbol_,string calldata story_,address creator_,uint256 supplyCap_,uint256 price_,address wallet_,uint256 fee_,address circuits_) external {
        require(!initialized,"INITIALIZED");initialized=true;_initialize(name_,symbol_,story_,creator_,supplyCap_,price_,wallet_,fee_,circuits_);
    }
    function _initialize(string memory name_,string memory symbol_,string memory story_,address creator_,uint256 cap_,uint256 price_,address wallet_,uint256 fee_,address circuits_) private {
        require(creator_!=address(0)&&wallet_!=address(0)&&circuits_!=address(0),"ZERO");creator=creator_;protocolWallet=wallet_;circuits=circuits_;mintPrice=price_;protocolFee=fee_;supplyCap=cap_;cpuName=name_;cpuSymbol=symbol_;story=story_;
    }
    function supportsInterface(bytes4 id) external pure returns(bool){return id==0x01ffc9a7||id==0xd9b67a26||id==0x0e89341c;}
    function uri(uint256 id) external view returns(string memory){require(id<=LATCH,"TYPE");return string.concat('data:application/json;base64,',ROtapMetadata.base64(bytes(string.concat('{"name":"',ROtapMetadata.escape(cpuName),id==NAND?' NAND':' LATCH','","description":"',ROtapMetadata.escape(story),'","decimals":0}'))));}
    function balanceOf(address account,uint256 id) public view returns(uint256){require(account!=address(0),"ZERO");return balances[id][account];}
    function balanceOfBatch(address[] calldata accounts,uint256[] calldata ids) external view returns(uint256[] memory result){
        require(accounts.length==ids.length,"LENGTH");result=new uint256[](ids.length);
        for(uint256 i;i<ids.length;i++)result[i]=balanceOf(accounts[i],ids[i]);
    }
    function quoteMint(address account,uint256 amount) external view returns(uint256){account;return mintPrice*amount+protocolFee;}
    function mint(uint256 id,uint256 amount) external payable nonReentrant {
        require(id<=LATCH&&amount>0,"AMOUNT");require(minted+amount<=supplyCap,"SUPPLY");
        require(typeCap[id]==0||mintedOf[id]+amount<=typeCap[id],"TYPE_CAP");require(walletCap==0||mintedBy[msg.sender]+amount<=walletCap,"WALLET_CAP");
        uint256 price=mintPrice*amount;uint256 fee=protocolFee;
        require(msg.value==price+fee,"PAYMENT");
        minted+=amount;mintedOf[id]+=amount;mintedBy[msg.sender]+=amount;
        balances[id][msg.sender]+=amount;owed[creator]+=price;owed[protocolWallet]+=fee;
        emit TransferSingle(msg.sender,address(0),msg.sender,id,amount);
        accept(msg.sender,address(0),msg.sender,id,amount,"");
    }
    function withdraw() external nonReentrant {
        uint256 amount=owed[msg.sender];require(amount>0,"NOTHING");owed[msg.sender]=0;
        (bool ok,)=payable(msg.sender).call{value:amount}("");require(ok,"TRANSFER");
    }
    function setApprovalForAll(address operator,bool approved) external {
        require(operator!=msg.sender,"SELF");isApprovedForAll[msg.sender][operator]=approved;
        emit ApprovalForAll(msg.sender,operator,approved);
    }
    function safeTransferFrom(address from,address to,uint256 id,uint256 amount,bytes calldata data) external {
        require(msg.sender==from||isApprovedForAll[from][msg.sender],"AUTH");move(from,to,id,amount);
        emit TransferSingle(msg.sender,from,to,id,amount);accept(msg.sender,from,to,id,amount,data);
    }
    function safeBatchTransferFrom(address from,address to,uint256[] calldata ids,uint256[] calldata amounts,bytes calldata data) external {
        require(msg.sender==from||isApprovedForAll[from][msg.sender],"AUTH");require(ids.length==amounts.length,"LENGTH");
        for(uint256 i;i<ids.length;i++)move(from,to,ids[i],amounts[i]);
        emit TransferBatch(msg.sender,from,to,ids,amounts);
        if(to.code.length>0){(bool ok,bytes memory result)=to.call(abi.encodeWithSignature("onERC1155BatchReceived(address,address,uint256[],uint256[],bytes)",msg.sender,from,ids,amounts,data));require(ok&&result.length>=32&&abi.decode(result,(bytes4))==0xbc197c81,"RECEIVER");}
    }
    function burnFrom(address from,uint256 id,uint256 amount) external {
        require(msg.sender==circuits,"AUTH");require(balances[id][from]>=amount,"BALANCE");
        balances[id][from]-=amount;emit TransferSingle(msg.sender,from,address(0),id,amount);
    }
    function move(address from,address to,uint256 id,uint256 amount) private {
        require(to!=address(0)&&balances[id][from]>=amount,"BALANCE");balances[id][from]-=amount;balances[id][to]+=amount;
    }
    function accept(address operator,address from,address to,uint256 id,uint256 amount,bytes memory data) private {
        if(to.code.length>0){(bool ok,bytes memory result)=to.call(abi.encodeWithSignature("onERC1155Received(address,address,uint256,uint256,bytes)",operator,from,id,amount,data));require(ok&&result.length>=32&&abi.decode(result,(bytes4))==0xf23a6e61,"RECEIVER");}
    }
}

library ROtapMetadata {
    function decimal(uint256 value) internal pure returns(string memory){if(value==0)return '0';uint256 v=value;uint256 n;while(v>0){n++;v/=10;}bytes memory out=new bytes(n);while(value>0){out[--n]=bytes1(uint8(48+value%10));value/=10;}return string(out);}
    function escape(string memory value) internal pure returns(string memory){bytes memory input=bytes(value);bytes memory out=new bytes(input.length*6);bytes16 hexes='0123456789abcdef';uint256 n;for(uint256 i;i<input.length;i++){uint8 b=uint8(input[i]);if(b==34||b==92){out[n++]=0x5c;out[n++]=input[i];}else if(b<32){out[n++]=0x5c;out[n++]='u';out[n++]='0';out[n++]='0';out[n++]=hexes[b>>4];out[n++]=hexes[b&15];}else out[n++]=input[i];}assembly ("memory-safe"){mstore(out,n)}return string(out);}
    function base64(bytes memory input) internal pure returns(string memory){bytes memory alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';bytes memory out=new bytes(4*((input.length+2)/3));uint256 j;for(uint256 i;i<input.length;i+=3){uint256 v=uint256(uint8(input[i]))<<16;if(i+1<input.length)v|=uint256(uint8(input[i+1]))<<8;if(i+2<input.length)v|=uint8(input[i+2]);out[j++]=alphabet[(v>>18)&63];out[j++]=alphabet[(v>>12)&63];out[j++]=i+1<input.length?alphabet[(v>>6)&63]:bytes1('=');out[j++]=i+2<input.length?alphabet[v&63]:bytes1('=');}return string(out);}
}

ROtapCircuits.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRuntime.sol';
import './ROtapTransistors.sol';
import './ROtapReferenceRuntime.sol';

interface IROtapTransferHook {function beforeCircuitTransfer(uint256 id,address from,address to) external;}
interface IROtapAccountList {function isAccount(address account) external view returns(bool);function accountOf(address circuits,uint256 id) external view returns(address);}
interface IROtapFactoryDefaults {function protocolWallet() external view returns(address);function defaultTapeoutFee() external view returns(uint256);}

/// Persistent circuit programs. REF execution is separate from mining eligibility.
contract ROtapCircuits {
    string public name;string public symbol;
    address public TREASURY;address public initializer;
    address public factory;
    uint256 public TAPEOUT_FEE;
    ROtapTransistors public transistors;
    bool private initialized;
    address public mining;
    bool public miningConfigured;
    address public accountOpener;
    uint256 public nextId;
    uint256 public owedFees;
    uint256 private lock;
    struct Circuit {bytes program;uint32 nIn;uint32 nOut;ROtapRuntime.Metrics metrics;uint32 states;uint32 gateCount;bool references;}
    mapping(uint256=>Circuit) private data;
    mapping(uint256=>address) private owners;
    mapping(address=>uint256) private balances;
    mapping(uint256=>address) public getApproved;
    mapping(address=>mapping(address=>bool)) public isApprovedForAll;
    mapping(address=>uint256[]) private ownedIds;mapping(uint256=>uint256) private ownedIndex;
    event Transfer(address indexed from,address indexed to,uint256 indexed tokenId);
    event Approval(address indexed owner,address indexed approved,uint256 indexed tokenId);
    event ApprovalForAll(address indexed owner,address indexed operator,bool approved);
    event TapedOut(uint256 indexed circuitId,address indexed owner,uint32 nIn,uint32 nOut,uint32 nState,uint32 gateCount);
    event TapeoutFeeSet(uint256 fee);
    modifier nonReentrant(){require(lock==0,'REENTRANCY');lock=1;_;lock=0;}
    constructor(address treasury,uint256 mintPrice,uint256 protocolFee,uint256 tapeoutFee){
        initialized=true;
        if(treasury!=address(0)){TREASURY=treasury;initializer=msg.sender;factory=msg.sender;TAPEOUT_FEE=tapeoutFee;name='ROtap Circuit';symbol='ROTC';transistors=new ROtapTransistors(treasury,treasury,address(this),mintPrice,protocolFee);}
    }
    function initialize(string calldata name_,string calldata symbol_,address transistors_,address factory_) external {
        require(!initialized&&msg.sender==factory_&&factory_.code.length>0&&transistors_.code.length>0,'INITIALIZED');initialized=true;
        name=name_;symbol=symbol_;factory=factory_;initializer=factory_;transistors=ROtapTransistors(transistors_);TREASURY=IROtapFactoryDefaults(factory_).protocolWallet();TAPEOUT_FEE=IROtapFactoryDefaults(factory_).defaultTapeoutFee();
    }
    function configureMining(address hook) external {require(msg.sender==initializer&&!miningConfigured&&hook.code.length>0,'AUTH');mining=hook;miningConfigured=true;}
    function configureAccounts(address opener) external {require(msg.sender==initializer&&accountOpener==address(0)&&opener.code.length>0,'AUTH');accountOpener=opener;}
    function ownerOf(uint256 id) public view returns(address){address account=owners[id];require(account!=address(0),'TOKEN');return account;}
    function balanceOf(address account) external view returns(uint256){require(account!=address(0),'ZERO');return balances[account];}
    function tokensOfOwner(address account,uint256 offset,uint256 limit) external view returns(uint256[] memory result){require(limit<=200,'LIMIT');uint256 count=ownedIds[account].length;if(offset>=count)return new uint256[](0);uint256 end=offset+limit;if(end>count)end=count;result=new uint256[](end-offset);for(uint256 i=offset;i<end;i++)result[i-offset]=ownedIds[account][i];}
    function supportsInterface(bytes4 id) external pure returns(bool){return id==0x01ffc9a7||id==0x80ac58cd||id==0x5b5e139f;}
    function tokenURI(uint256 id) external view returns(string memory){ownerOf(id);Circuit storage c=data[id];return string.concat('data:application/json;base64,',ROtapMetadata.base64(bytes(string.concat('{"name":"',ROtapMetadata.escape(name),' #',ROtapMetadata.decimal(id),'","description":"On-chain circuit program","attributes":[{"trait_type":"Inputs","value":',ROtapMetadata.decimal(c.nIn),'},{"trait_type":"Outputs","value":',ROtapMetadata.decimal(c.nOut),'},{"trait_type":"State bits","value":',ROtapMetadata.decimal(c.states),'},{"trait_type":"Gates","value":',ROtapMetadata.decimal(c.gateCount),'}]}'))));}
    function transistorsContract() external view returns(address){return address(transistors);}
    function circuitInfo(uint256 id) external view returns(uint32 nIn,uint32 nOut,uint32 nState,uint32 gateCount){ownerOf(id);Circuit storage c=data[id];return(c.nIn,c.nOut,c.states,c.gateCount);}
    function netlist(uint256 id) external view returns(bytes memory){ownerOf(id);return data[id].program;}
    function circuitMetrics(uint256 id) external view returns(ROtapRuntime.Metrics memory){ownerOf(id);require(!data[id].references,'REF_INELIGIBLE');return data[id].metrics;}
    function hasReferences(uint256 id) external view returns(bool){ownerOf(id);return data[id].references;}
    function tapeout(bytes calldata program,uint32 nIn,uint32 nOut) external payable nonReentrant returns(uint256 id){
        require(msg.value==TAPEOUT_FEE,'PAYMENT');
        ROtapReferenceRuntime.Layout memory layout=ROtapReferenceRuntime.describe(program,nIn,nOut,factory);
        ROtapRuntime.Metrics memory m;
        if(!layout.hasRefs)m=ROtapRuntime.inspect(program,nIn,nOut);else{m.nand=layout.nand;m.latch=layout.latch;}
        require(layout.gates>0,'EMPTY');
        if(m.nand>0)transistors.burnFrom(msg.sender,0,m.nand);
        if(m.latch>0)transistors.burnFrom(msg.sender,1,m.latch);
        id=++nextId;data[id]=Circuit(program,nIn,nOut,m,layout.states,layout.gates,layout.hasRefs);owners[id]=msg.sender;balances[msg.sender]++;ownedIndex[id]=ownedIds[msg.sender].length;ownedIds[msg.sender].push(id);owedFees+=msg.value;
        emit Transfer(address(0),msg.sender,id);emit TapedOut(id,msg.sender,nIn,nOut,layout.states,layout.gates);
        accept(msg.sender,address(0),msg.sender,id,'');
    }
    function eval(uint256 id,bytes calldata inputs) external view returns(bytes memory outputs){
        ownerOf(id);Circuit storage c=data[id];require(c.states==0,'SEQUENTIAL');
        if(c.references)(,outputs)=ROtapReferenceRuntime.run(c.program,c.nIn,c.nOut,'',inputs,factory);else (,outputs)=ROtapRuntime.run(c.program,c.nIn,c.nOut,'',inputs);
    }
    function step(uint256 id,bytes calldata state,bytes calldata inputs) external view returns(bytes memory newState,bytes memory outputs){
        ownerOf(id);Circuit storage c=data[id];if(c.references)return ROtapReferenceRuntime.run(c.program,c.nIn,c.nOut,state,inputs,factory);return ROtapRuntime.run(c.program,c.nIn,c.nOut,state,inputs);
    }
    function approve(address operator,uint256 id) external {address account=ownerOf(id);require(msg.sender==account||isApprovedForAll[account][msg.sender],'AUTH');require(operator!=account,'SELF');getApproved[id]=operator;emit Approval(account,operator,id);}
    function setApprovalForAll(address operator,bool approved) external {require(operator!=msg.sender,'SELF');isApprovedForAll[msg.sender][operator]=approved;emit ApprovalForAll(msg.sender,operator,approved);}
    function transferFrom(address from,address to,uint256 id) public nonReentrant {
        require(ownerOf(id)==from&&to!=address(0),'OWNER');require(msg.sender==from||getApproved[id]==msg.sender||isApprovedForAll[from][msg.sender],'AUTH');
        if(mining!=address(0))IROtapTransferHook(mining).beforeCircuitTransfer(id,from,to);
        delete getApproved[id];uint256 index=ownedIndex[id];uint256 last=ownedIds[from][ownedIds[from].length-1];ownedIds[from][index]=last;ownedIndex[last]=index;ownedIds[from].pop();ownedIndex[id]=ownedIds[to].length;ownedIds[to].push(id);balances[from]--;balances[to]++;owners[id]=to;emit Transfer(from,to,id);
    }
    function safeTransferFrom(address from,address to,uint256 id) external {safeTransferFrom(from,to,id,'');}
    function safeTransferFrom(address from,address to,uint256 id,bytes memory extra) public {transferFrom(from,to,id);accept(msg.sender,from,to,id,extra);}
    function accept(address operator,address from,address to,uint256 id,bytes memory extra) private {
        if(to.code.length>0){(bool ok,bytes memory result)=to.call(abi.encodeWithSignature('onERC721Received(address,address,uint256,bytes)',operator,from,id,extra));require(ok&&result.length>=32&&abi.decode(result,(bytes4))==0x150b7a02,'RECEIVER');}
    }
    function sweepFees() external nonReentrant {require(msg.sender==TREASURY,'AUTH');uint256 amount=owedFees;owedFees=0;(bool ok,)=payable(TREASURY).call{value:amount}('');require(ok,'TRANSFER');}
}

ROtapReferenceRuntime.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRuntime.sol';
interface IROtapCPURegistry {function isCPU(address target) external view returns(bool);}
interface IROtapReferencedCircuit {
    function circuitInfo(uint256 id) external view returns(uint32,uint32,uint32,uint32);
    function step(uint256 id,bytes calldata state,bytes calldata inputs) external view returns(bytes memory,bytes memory);
}
/// REF encoding and ordered state packing verified with original-chain read-only simulations.
library ROtapReferenceRuntime {
    struct Layout {uint32 nand;uint32 latch;uint32 states;uint32 gates;uint256 wires;bool hasRefs;}
    struct Reference {address target;uint64 id;uint8 nIn;uint8 nOut;uint32 states;uint32 gates;}
    function referenceAt(bytes memory program,uint256 pos,address registry) internal view returns(Reference memory r){
        require(pos+30<=program.length,'TRUNCATED_REF');uint160 target;
        for(uint256 i;i<20;i++)target=(target<<8)|uint8(program[pos+i]);r.target=address(target);
        for(uint256 i;i<8;i++)r.id=(r.id<<8)|uint8(program[pos+20+i]);
        r.nIn=uint8(program[pos+28]);r.nOut=uint8(program[pos+29]);require(pos+30+uint256(r.nIn)*3<=program.length,'TRUNCATED_REF');
        require(registry.code.length>0&&IROtapCPURegistry(registry).isCPU(r.target),'REF_UNREGISTERED');
        (uint32 inputs,uint32 outputs,uint32 states,uint32 gates)=IROtapReferencedCircuit(r.target).circuitInfo(r.id);
        require(inputs==r.nIn&&outputs==r.nOut,'REF_SHAPE');r.states=states;r.gates=gates;
    }
    function describe(bytes memory program,uint32 nIn,uint32 nOut,address registry) internal view returns(Layout memory l){
        l.wires=2+uint256(nIn);uint256 pos;
        while(pos<program.length){uint8 op=uint8(program[pos++]);
            if(op==0){require(pos+6<=program.length,'TRUNCATED');l.nand++;l.gates++;l.wires++;pos+=6;}
            else if(op==1){require(pos+3<=program.length,'TRUNCATED');l.latch++;l.states++;l.gates++;l.wires++;pos+=3;}
            else if(op==2){Reference memory r=referenceAt(program,pos,registry);l.hasRefs=true;l.states+=r.states;l.gates+=r.gates;l.wires+=r.nOut;pos+=30+uint256(r.nIn)*3;}
            else revert('UNSUPPORTED_OPCODE');
        }
        require(nOut>0&&nOut<=l.wires,'OUTPUTS');uint256 wire=2+uint256(nIn);pos=0;
        while(pos<program.length){uint8 op=uint8(program[pos++]);
            if(op==0){require(ROtapRuntime.u24(program,pos)<wire&&ROtapRuntime.u24(program,pos+3)<wire,'FORWARD_NAND');pos+=6;wire++;}
            else if(op==1){require(ROtapRuntime.u24(program,pos)<l.wires,'STATE_WIRE');pos+=3;wire++;}
            else{uint256 inputs=uint8(program[pos+28]);for(uint256 i;i<inputs;i++)require(ROtapRuntime.u24(program,pos+30+i*3)<wire,'REF_FUTURE_SIGNAL');wire+=uint8(program[pos+29]);pos+=30+inputs*3;}
        }
    }
    function run(bytes memory program,uint32 nIn,uint32 nOut,bytes memory state,bytes memory inputs,address registry) internal view returns(bytes memory next,bytes memory outputs){
        Layout memory l=describe(program,nIn,nOut,registry);require(inputs.length==(uint256(nIn)+7)/8,'INPUT_LENGTH');require(state.length==0||state.length==(uint256(l.states)+7)/8,'STATE_LENGTH');
        bool[] memory wires=new bool[](l.wires);wires[1]=true;for(uint256 i;i<nIn;i++)wires[2+i]=ROtapRuntime.bit(inputs,i);
        next=new bytes((uint256(l.states)+7)/8);outputs=new bytes((uint256(nOut)+7)/8);uint256[] memory latchSources=new uint256[](l.latch);uint256[] memory latchOffsets=new uint256[](l.latch);
        uint256 pos;uint256 wire=2+uint256(nIn);uint256 stateOffset;uint256 latchIndex;
        while(pos<program.length){uint8 op=uint8(program[pos++]);
            if(op==0){wires[wire++]=!(wires[ROtapRuntime.u24(program,pos)]&&wires[ROtapRuntime.u24(program,pos+3)]);pos+=6;}
            else if(op==1){latchSources[latchIndex]=ROtapRuntime.u24(program,pos);latchOffsets[latchIndex++]=stateOffset;wires[wire++]=ROtapRuntime.bit(state,stateOffset++);pos+=3;}
            else{Reference memory r=referenceAt(program,pos,registry);bytes memory refInputs=new bytes((uint256(r.nIn)+7)/8);bytes memory refState=new bytes((uint256(r.states)+7)/8);
                for(uint256 i;i<r.nIn;i++)if(wires[ROtapRuntime.u24(program,pos+30+i*3)])ROtapRuntime.setBit(refInputs,i);
                for(uint256 i;i<r.states;i++)if(ROtapRuntime.bit(state,stateOffset+i))ROtapRuntime.setBit(refState,i);
                (bytes memory refNext,bytes memory refOutputs)=IROtapReferencedCircuit(r.target).step(r.id,refState,refInputs);
                require(refNext.length==refState.length&&refOutputs.length==(uint256(r.nOut)+7)/8,'REF_RESULT');
                for(uint256 i;i<r.states;i++)if(ROtapRuntime.bit(refNext,i))ROtapRuntime.setBit(next,stateOffset+i);
                for(uint256 i;i<r.nOut;i++)wires[wire+i]=ROtapRuntime.bit(refOutputs,i);
                stateOffset+=r.states;wire+=r.nOut;pos+=30+uint256(r.nIn)*3;
            }
        }
        for(uint256 i;i<l.latch;i++)if(wires[latchSources[i]])ROtapRuntime.setBit(next,latchOffsets[i]);
        for(uint256 i;i<nOut;i++)if(wires[wires.length-nOut+i])ROtapRuntime.setBit(outputs,i);
    }
}

