// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

interface IROtapBoostSync {function beforeFactorChange(address holder) external;function afterFactorChange(address holder) external;function beforeFactorChangeForKeys(address holder,bytes32[] calldata keys) external;function afterFactorChangeForKeys(address holder,bytes32[] calldata keys) external;}

/// Native-asset staking candidate; ETH thresholds must be fixed in the final release manifest.
contract ROtapStakeBoost {
    uint256 public constant UNSTAKE_DELAY=7 days;
    uint256[5] public stakeTiers;
    uint256[5] public stakeBoosts=[uint256(500),700,900,1200,1500];
    address public immutable mining;
    mapping(address=>uint256) public staked;
    struct Exit {uint256 amount;uint256 unlockAt;}
    mapping(address=>Exit) public unstaking;
    uint256 public totalStaked;uint256 public totalUnstaking;
    uint256 private entered;
    event Staked(address indexed account,uint256 amount);
    event Unstaked(address indexed account,uint256 amount,uint256 unlockAt);
    event Withdrawn(address indexed account,uint256 amount);
    modifier nonReentrant(){require(entered==0,'REENTRANCY');entered=1;_;entered=0;}
    constructor(address mining_,uint256[5] memory tiers){
        require(mining_.code.length>0,'MINING');mining=mining_;
        for(uint256 i;i<5;i++)require(tiers[i]>0&&(i==0||tiers[i]>tiers[i-1]),'TIERS');stakeTiers=tiers;
    }
    function stakeBpsOf(address account) public view returns(uint256){uint256 amount=staked[account];for(uint256 i=5;i>0;i--)if(amount>=stakeTiers[i-1])return stakeBoosts[i-1];return 0;}
    function factorBps(address account) public view virtual returns(uint256){return 10000+stakeBpsOf(account);}
    function beforeChange(bytes32[] memory keys,bool selected) internal {if(selected)IROtapBoostSync(mining).beforeFactorChangeForKeys(msg.sender,keys);else IROtapBoostSync(mining).beforeFactorChange(msg.sender);}
    function afterChange(bytes32[] memory keys,bool selected) internal {if(selected)IROtapBoostSync(mining).afterFactorChangeForKeys(msg.sender,keys);else IROtapBoostSync(mining).afterFactorChange(msg.sender);}
    function stake() external payable nonReentrant {stakeInternal(new bytes32[](0),false);}
    function stakeWithKeys(bytes32[] calldata keys) external payable nonReentrant {stakeInternal(keys,true);}
    function stakeInternal(bytes32[] memory keys,bool selected) private {
        require(msg.value>0,'AMOUNT');beforeChange(keys,selected);
        staked[msg.sender]+=msg.value;totalStaked+=msg.value;
        afterChange(keys,selected);emit Staked(msg.sender,msg.value);
    }
    function unstake(uint256 amount) external nonReentrant {unstakeInternal(amount,new bytes32[](0),false);}
    function unstakeWithKeys(uint256 amount,bytes32[] calldata keys) external nonReentrant {unstakeInternal(amount,keys,true);}
    function unstakeInternal(uint256 amount,bytes32[] memory keys,bool selected) private {
        require(amount>0&&staked[msg.sender]>=amount,'BALANCE');beforeChange(keys,selected);
        staked[msg.sender]-=amount;totalStaked-=amount;totalUnstaking+=amount;
        Exit storage exit=unstaking[msg.sender];exit.amount+=amount;exit.unlockAt=block.timestamp+UNSTAKE_DELAY;
        afterChange(keys,selected);emit Unstaked(msg.sender,amount,exit.unlockAt);
    }
    function withdraw(address account) external nonReentrant {
        Exit memory exit=unstaking[account];require(exit.amount>0&&block.timestamp>=exit.unlockAt,'LOCKED');
        delete unstaking[account];totalUnstaking-=exit.amount;
        (bool ok,)=payable(account).call{value:exit.amount}('');require(ok,'TRANSFER');emit Withdrawn(account,exit.amount);
    }
}

ROtapRewardStakeBoost.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import './ROtapStakeBoost.sol';

interface IROtapStakeToken {
    function decimals() external view returns(uint8);
    function balanceOf(address account) external view returns(uint256);
    function transferFrom(address from,address to,uint256 amount) external returns(bool);
    function transfer(address to,uint256 amount) external returns(bool);
}

/// User-authorized asset adaptation: ROTAP replaces the reference BEM staking asset.
contract ROtapRewardStakeBoost is ROtapStakeBoost {
    IROtapStakeToken public immutable rewardToken;
    uint256[5] public rewardStakeTiers=[uint256(200e8),600e8,1000e8,1500e8,2000e8];
    mapping(address=>uint256) public rewardStaked;
    mapping(address=>Exit) public rewardUnstaking;
    uint256 public totalRewardStaked;
    uint256 public totalRewardUnstaking;
    event RewardStaked(address indexed account,uint256 amount);
    event RewardUnstaked(address indexed account,uint256 amount,uint256 unlockAt);
    event RewardWithdrawn(address indexed account,uint256 amount);

    constructor(address mining_,uint256[5] memory nativeTiers,address token_) ROtapStakeBoost(mining_,nativeTiers) {
        require(token_.code.length>0,'TOKEN');
        rewardToken=IROtapStakeToken(token_);
        require(rewardToken.decimals()==8,'DECIMALS');
    }
    function rewardStakeBpsOf(uint256 amount) public view returns(uint256){
        for(uint256 i=5;i>0;i--)if(amount>=rewardStakeTiers[i-1])return stakeBoosts[i-1];return 0;
    }
    function factorBps(address account) public view virtual override returns(uint256){
        return 10000+stakeBpsOf(account)+rewardStakeBpsOf(rewardStaked[account]);
    }
    function stakeReward(uint256 amount) external nonReentrant {stakeRewardInternal(amount,new bytes32[](0),false);}
    function stakeRewardWithKeys(uint256 amount,bytes32[] calldata keys) external nonReentrant {stakeRewardInternal(amount,keys,true);}
    function stakeRewardInternal(uint256 amount,bytes32[] memory keys,bool selected) private {
        require(amount>0,'AMOUNT');beforeChange(keys,selected);
        uint256 beforeBalance=rewardToken.balanceOf(address(this));
        require(rewardToken.transferFrom(msg.sender,address(this),amount),'TRANSFER');
        require(rewardToken.balanceOf(address(this))==beforeBalance+amount,'TOKEN_AMOUNT');
        rewardStaked[msg.sender]+=amount;totalRewardStaked+=amount;
        afterChange(keys,selected);emit RewardStaked(msg.sender,amount);
    }
    function unstakeReward(uint256 amount) external nonReentrant {unstakeRewardInternal(amount,new bytes32[](0),false);}
    function unstakeRewardWithKeys(uint256 amount,bytes32[] calldata keys) external nonReentrant {unstakeRewardInternal(amount,keys,true);}
    function unstakeRewardInternal(uint256 amount,bytes32[] memory keys,bool selected) private {
        require(amount>0&&rewardStaked[msg.sender]>=amount,'BALANCE');
        beforeChange(keys,selected);
        rewardStaked[msg.sender]-=amount;totalRewardStaked-=amount;totalRewardUnstaking+=amount;
        Exit storage exit=rewardUnstaking[msg.sender];exit.amount+=amount;exit.unlockAt=block.timestamp+UNSTAKE_DELAY;
        afterChange(keys,selected);emit RewardUnstaked(msg.sender,amount,exit.unlockAt);
    }
    function withdrawReward(address account) external nonReentrant {
        Exit memory exit=rewardUnstaking[account];require(exit.amount>0&&block.timestamp>=exit.unlockAt,'LOCKED');
        delete rewardUnstaking[account];totalRewardUnstaking-=exit.amount;
        require(rewardToken.transfer(account,exit.amount),'TRANSFER');emit RewardWithdrawn(account,exit.amount);
    }
}

ROtapBoost.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRewardStakeBoost.sol';
interface IROtapMiningLedger {function ledger() external view returns(address);}
interface IROtapBoostLedger {function startTime() external view returns(uint256);function HALVING_PERIOD() external view returns(uint256);function token() external view returns(address);}
contract ROtapBoost is ROtapRewardStakeBoost {
    uint256 public constant MAX_BOOST_BPS=5000;
    uint256 public constant BURN_WINDOW=180 days;
    uint256[5] public burnTiers;
    address public immutable treasury;
    IROtapBoostLedger public immutable rewardLedger;
    uint256 public totalBurned;
    struct Burn {uint16 bps;uint64 until;}
    mapping(address=>Burn) public burns;
    event Burned(address indexed account,uint256 amount,uint256 bps,uint256 until);
    constructor(address mining_,uint256[5] memory stakeMins,address token_,address treasury_,uint256[5] memory burnMins)
        ROtapRewardStakeBoost(mining_,stakeMins,token_) {
        require(treasury_!=address(0),'ZERO');treasury=treasury_;
        rewardLedger=IROtapBoostLedger(IROtapMiningLedger(mining_).ledger());
        require(rewardLedger.token()==token_,'REWARD_TOKEN');
        for(uint256 i;i<5;i++)require(burnMins[i]>0&&(i==0||burnMins[i]>burnMins[i-1]),'TIERS');burnTiers=burnMins;
    }
    function startTime() public view returns(uint256){return rewardLedger.startTime();}
    function eraLength() public view returns(uint256){return rewardLedger.HALVING_PERIOD();}
    function burnBpsNow() public view returns(uint256){
        uint256 genesis=startTime();if(block.timestamp<genesis)return 0;uint256 elapsed=block.timestamp-genesis;
        uint256 period=eraLength();if(period==0)return 0;uint256 era=elapsed/period;
        if(era>=4||elapsed%period>=BURN_WINDOW)return 0;return 1600-era*400;
    }
    function burnDurationOf(uint256 amount) public view returns(uint256){
        uint256[5] memory durations=[uint256(7 days),14 days,28 days,60 days,180 days];
        for(uint256 i=5;i>0;i--)if(amount>=burnTiers[i-1])return durations[i-1];return 0;
    }
    function burnBpsOf(address account) public view returns(uint256){Burn memory b=burns[account];return block.timestamp<b.until?b.bps:0;}
    function factorBps(address account) public view override returns(uint256){
        uint256 extra=stakeBpsOf(account)+rewardStakeBpsOf(rewardStaked[account])+burnBpsOf(account);
        return 10000+(extra>MAX_BOOST_BPS?MAX_BOOST_BPS:extra);
    }
    function burn() external payable nonReentrant {burnInternal(new bytes32[](0),false);}
    function burnWithKeys(bytes32[] calldata keys) external payable nonReentrant {burnInternal(keys,true);}
    function burnInternal(bytes32[] memory keys,bool selected) private {
        require(burns[msg.sender].until<=block.timestamp,'ACTIVE');uint256 bps=burnBpsNow();require(bps>0,'CLOSED');
        uint256 duration=burnDurationOf(msg.value);require(duration>0,'AMOUNT');
        beforeChange(keys,selected);
        uint256 until=block.timestamp+duration;require(until<=type(uint64).max,'TIME');burns[msg.sender]=Burn(uint16(bps),uint64(until));totalBurned+=msg.value;
        (bool ok,)=payable(treasury).call{value:msg.value}('');require(ok,'TRANSFER');
        afterChange(keys,selected);emit Burned(msg.sender,msg.value,bps,until);
    }
}

ROtapSamplingPolicy.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRuntime.sol';
import './ROtapTaskRegistry.sol';
interface IROtapSamplingCircuit {function circuitInfo(uint256) external view returns(uint32,uint32,uint32,uint32);function netlist(uint256) external view returns(bytes memory);}

/// Initial sampling parameters and hash encoding matched against original-chain traces.
/// Governance changes to sampling budgets still require reference verification.
contract ROtapSamplingPolicy {
    ROtapTaskRegistry public immutable registry;
    address public immutable owner;address public controller;bool public isSealed;
    uint256 public maxRunGas=12_000_000;
    uint256 public constant sampleGasBudget=8_000_000;
    uint32 public constant MIN_SAMPLES=3;
    uint32 public constant maxSamples=32;
    constructor(address registry_){require(registry_.code.length>0,'REGISTRY');registry=ROtapTaskRegistry(registry_);owner=msg.sender;}
    function setController(address controller_) external {require(msg.sender==owner&&controller==address(0)&&controller_.code.length>0,'AUTH');controller=controller_;}
    function raiseMaxRunGas(uint256 limit) external {require(msg.sender==(controller==address(0)?owner:controller)&&!isSealed&&limit>maxRunGas,'AUTH');maxRunGas=limit;}
    function seal() external {require(msg.sender==controller,'AUTH');isSealed=true;}
    function runGasFor(uint32 gates,uint32 cycles) public pure returns(uint256){return (50000+uint256(gates)*3000)*cycles;}
    function sampleCountFor(uint32 gates,uint32 cycles) public pure returns(uint32){
        require(cycles>0,'CYCLES');uint256 count=sampleGasBudget/runGasFor(gates,cycles);if(count>maxSamples)count=maxSamples;if(count<MIN_SAMPLES)count=MIN_SAMPLES;return uint32(count);
    }
    function checkBudget(uint32 gates,uint32 cycles,uint256 samples) external view returns(bool){return cycles>0&&samples>=MIN_SAMPLES&&samples<=maxSamples&&runGasFor(gates,cycles)*samples<=maxRunGas;}
    function indexes(bytes32 anchorHash,address circuits,uint256 circuitId,uint32 vectorCount,uint32 count) public pure returns(uint32[] memory result){
        require(vectorCount>0&&count>=MIN_SAMPLES&&count<=maxSamples,'CONFIG');result=new uint32[](count);
        for(uint32 i;i<count;i++)result[i]=uint32(uint256(keccak256(abi.encodePacked(anchorHash,circuits,circuitId,i)))%vectorCount);
    }
    function sampleIndexes(address circuits,uint256 circuitId,uint32 taskId,uint256 anchorBlock) external view returns(uint32[] memory){
        bytes32 anchorHash=blockhash(anchorBlock);require(anchorHash!=bytes32(0),'ANCHOR');ROtapTaskRegistry.Task memory task=registry.getTask(taskId);
        (uint32 nIn,uint32 nOut,,)=IROtapSamplingCircuit(circuits).circuitInfo(circuitId);bytes memory program=IROtapSamplingCircuit(circuits).netlist(circuitId);
        uint32 count=sampleCountFor(ROtapRuntime.liveGateCount(program,nIn,nOut),task.cycles);
        return indexes(anchorHash,circuits,circuitId,task.vectorCount,count);
    }
}

ROtapTaskRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRuntime.sol';

interface IROtapExecutable {
    function circuitInfo(uint256 id) external view returns(uint32,uint32,uint32,uint32);
    function circuitMetrics(uint256 id) external view returns(ROtapRuntime.Metrics memory);
    function eval(uint256 id,bytes calldata inputs) external view returns(bytes memory);
    function step(uint256 id,bytes calldata state,bytes calldata inputs) external view returns(bytes memory,bytes memory);
}

/// Reference-verified task and Merkle proof candidate. Sampling integration is separate.
contract ROtapTaskRegistry {
    address public immutable owner;address public controller;bool public tasksFrozen;uint32 public taskCount;
    struct Task {string name;address referenceCircuits;uint256 referenceId;uint32 nIn;uint32 nOut;uint32 cycles;uint32 vectorCount;uint32 states;bytes32 vectorsRoot;uint256 refArea;uint256 refCost;bool active;}
    mapping(uint32=>Task) private tasks;
    event TaskAdded(uint32 indexed taskId,bytes32 vectorsRoot,address referenceCircuits,uint256 referenceId);
    constructor(){owner=msg.sender;}
    modifier onlyAdministrator(){require(msg.sender==(controller==address(0)?owner:controller),'AUTH');_;}
    function setController(address controller_) external {require(msg.sender==owner&&controller==address(0)&&controller_.code.length>0,'AUTH');controller=controller_;}
    function freezeTasks() external onlyAdministrator {tasksFrozen=true;}
    function getTask(uint32 taskId) public view returns(Task memory){require(taskId>0&&taskId<=taskCount,'TASK');return tasks[taskId];}
    function inspectNetlist(bytes calldata program,uint32 nIn,uint32 nOut) external pure returns(ROtapRuntime.Metrics memory){return ROtapRuntime.inspect(program,nIn,nOut);}
    function liveGateCount(bytes calldata program,uint32 nIn,uint32 nOut) external pure returns(uint32){return ROtapRuntime.liveGateCount(program,nIn,nOut);}
    function vectorLeaf(uint256 index,bytes memory input,bytes memory expected) public pure returns(bytes32){return keccak256(bytes.concat(keccak256(abi.encode(index,input,expected))));}
    function checkProof(bytes32 root,bytes32 leaf,bytes32[] calldata proof) public pure returns(bool){
        bytes32 node=leaf;for(uint256 i;i<proof.length;i++)node=node<proof[i]?keccak256(abi.encodePacked(node,proof[i])):keccak256(abi.encodePacked(proof[i],node));return node==root;
    }
    function publish(string calldata name,address referenceCircuits,uint256 referenceId,uint32 cycles,uint32 vectorCount,bytes32 root,uint32[] calldata indexes,bytes[] calldata inputs,bytes[] calldata expected,bytes32[][] calldata proofs) external returns(uint32 taskId){
        require(msg.sender==(controller==address(0)?owner:controller),'AUTH');require(cycles>0&&cycles<=256&&vectorCount>=3&&root!=bytes32(0),'CONFIG');
        require(indexes.length>=3&&indexes.length==inputs.length&&inputs.length==expected.length&&inputs.length==proofs.length,'SAMPLES');
        (uint32 nIn,uint32 nOut,uint32 states,)=IROtapExecutable(referenceCircuits).circuitInfo(referenceId);
        require(states>0||cycles==1,'CYCLES');
        ROtapRuntime.Metrics memory metrics=IROtapExecutable(referenceCircuits).circuitMetrics(referenceId);require(metrics.area>0&&metrics.cost>0,'REFERENCE');
        Task memory task=Task(name,referenceCircuits,referenceId,nIn,nOut,cycles,vectorCount,states,root,metrics.burn,metrics.cost,true);
        for(uint256 i;i<indexes.length;i++){
            require(indexes[i]<vectorCount,'INDEX');
            require(checkProof(root,vectorLeaf(indexes[i],inputs[i],expected[i]),proofs[i]),'PROOF');
            require(keccak256(execute(task,referenceCircuits,referenceId,inputs[i]))==keccak256(expected[i]),'REFERENCE_OUTPUT');
        }
        taskId=++taskCount;tasks[taskId]=task;emit TaskAdded(taskId,root,referenceCircuits,referenceId);
    }
    function updateTaskRef(uint32 taskId,address referenceCircuits,uint256 referenceId) external onlyAdministrator {
        require(!tasksFrozen,'FROZEN');Task storage task=tasks[taskId];require(taskId>0&&taskId<=taskCount,'TASK');if(referenceCircuits==address(0)){task.active=false;return;}(uint32 nIn,uint32 nOut,uint32 states,)=IROtapExecutable(referenceCircuits).circuitInfo(referenceId);require(nIn==task.nIn&&nOut==task.nOut&&(states>0)==(task.states>0),'SHAPE');task.referenceCircuits=referenceCircuits;task.referenceId=referenceId;task.active=true;
    }
    function verifyOfficial(uint32 taskId,address circuits,uint256 circuitId,uint32 index,bytes calldata input,bytes calldata expected,bytes32[] calldata proof) external view returns(bool){
        Task memory task=getTask(taskId);require(index<task.vectorCount&&checkProof(task.vectorsRoot,vectorLeaf(index,input,expected),proof),'PROOF');
        return keccak256(execute(task,circuits,circuitId,input))==keccak256(expected);
    }
    function matchesReference(uint32 taskId,address circuits,uint256 circuitId,bytes calldata input) external view returns(bool){
        Task memory task=getTask(taskId);return keccak256(execute(task,circuits,circuitId,input))==keccak256(execute(task,task.referenceCircuits,task.referenceId,input));
    }
    function execute(Task memory task,address circuits,uint256 circuitId,bytes memory input) private view returns(bytes memory result){
        (uint32 nIn,uint32 nOut,uint32 states,)=IROtapExecutable(circuits).circuitInfo(circuitId);
        require(nIn==task.nIn&&nOut==task.nOut&&(states>0)==(task.states>0),'SHAPE');
        uint256 inputSize=(uint256(nIn)+7)/8;uint256 outputSize=(uint256(nOut)+7)/8;
        require(input.length==inputSize*task.cycles,'INPUT_LENGTH');result=new bytes(outputSize*task.cycles);bytes memory state;
        for(uint256 cycle;cycle<task.cycles;cycle++){
            bytes memory vector=new bytes(inputSize);for(uint256 j;j<inputSize;j++)vector[j]=input[cycle*inputSize+j];
            bytes memory outputs;
            if(states==0)outputs=IROtapExecutable(circuits).eval(circuitId,vector);else(state,outputs)=IROtapExecutable(circuits).step(circuitId,state,vector);
            require(outputs.length==outputSize,'OUTPUT_LENGTH');for(uint256 j;j<outputSize;j++)result[cycle*outputSize+j]=outputs[j];
        }
    }
    function bonusOf(uint32 taskId,uint256 cost) external view returns(uint256){
        Task memory task=getTask(taskId);if(cost==0)return 0;uint256 value=task.refArea*task.refCost/cost;uint256 lower=(task.refArea+3)/4;uint256 upper=task.refArea*4;
        return value<lower?lower:value>upper?upper:value;
    }
}

ROtapMining.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import './ROtapRuntime.sol';
import './ROtapTaskRegistry.sol';
import './ROtapContinuousLedger.sol';
import '@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol';

interface IROtapMinerCircuit is IROtapExecutable {function ownerOf(uint256) external view returns(address);function netlist(uint256) external view returns(bytes memory);function nextId() external view returns(uint256);}
interface IROtapSamplingPolicy {
    function sampleIndexes(address circuits,uint256 circuitId,uint32 taskId,uint256 anchorBlock) external view returns(uint32[] memory);
    function checkBudget(uint32 gates,uint32 cycles,uint256 samples) external view returns(bool);
    function sampleCountFor(uint32 gates,uint32 cycles) external view returns(uint32);
    function indexes(bytes32,address,uint256,uint32,uint32) external view returns(uint32[] memory);
}
interface IROtapFactor {function factorBps(address holder) external view returns(uint256);}
interface IROtapSamplingAdmin {function raiseMaxRunGas(uint256) external;function seal() external;function maxRunGas() external view returns(uint256);}

/// Mining lifecycle candidate. Final sampling policy and original task data are not supplied here.
contract ROtapMining is OwnableUpgradeable,PausableUpgradeable,UUPSUpgradeable {
    ROtapTaskRegistry public registry;
    ROtapContinuousLedger public ledger;
    IROtapSamplingPolicy public sampling;
    ROtapLedgerFactory public immutable ledgerFactory;
    uint256 public constant MAX_ANCHOR_AGE=200;
    uint256 public constant STOP_COOLDOWN=1200;
    uint256 public constant OWNER_HEAD_START=1800;
    bool public isSealed;uint32 public eligibleEpoch;
    address public boost;
    mapping(address=>uint256) public processorMultiplier;
    mapping(bytes32=>uint256) public armedAt;
    mapping(address=>mapping(bytes32=>uint256)) public designCommits;
    mapping(address=>mapping(bytes32=>uint256)) public designFirstUnusedId;
    struct Miner {address circuits;uint256 circuitId;uint32 taskId;bool active;bool revoked;uint256 restartAt;uint256 cost;uint256 burn;uint256 designAt;address holder;uint256 mult;}
    mapping(bytes32=>Miner) public miners;
    mapping(uint32=>mapping(address=>bytes32)) public bestSlot;
    mapping(uint32=>mapping(address=>uint256)) public bestCost;
    mapping(uint32=>mapping(address=>uint256)) public bestCommitBlock;
    mapping(uint32=>mapping(address=>uint256)) public bestTombstoneBlock;
    mapping(uint32=>mapping(address=>bytes[])) private counterexamples;
    mapping(address=>bytes32[]) private holderKeys;
    mapping(bytes32=>uint256) private holderIndex;
    bytes32[] private allKeys;
    event Started(bytes32 indexed key,address indexed holder,uint32 taskId);
    event Stopped(bytes32 indexed key);
    event Revoked(bytes32 indexed key,uint32 vectorIndex);
    event Demoted(bytes32 indexed key,bytes input);
    event Sealed();
    modifier unsealed(){require(!isSealed,'SEALED');_;}
    constructor(address registry_,address policy,uint256 genesis,uint256 period,uint256 rate,address ledgerFactory_){
        require(ledgerFactory_.code.length>0,'LEDGER_FACTORY');ledgerFactory=ROtapLedgerFactory(ledgerFactory_);_disableInitializers();if(registry_!=address(0)){_transferOwnership(msg.sender);configure(registry_,policy,genesis,period,rate);}
    }
    function initialize(address owner_,address registry_,address policy,uint256 genesis,uint256 period,uint256 rate) external initializer {__Ownable_init(owner_);__Pausable_init();__UUPSUpgradeable_init();configure(registry_,policy,genesis,period,rate);}
    function configure(address registry_,address policy,uint256 genesis,uint256 period,uint256 rate) private {
        require(registry_.code.length>0&&policy.code.length>0,'CONFIG');registry=ROtapTaskRegistry(registry_);sampling=IROtapSamplingPolicy(policy);
        ledger=ROtapContinuousLedger(ledgerFactory.create(address(this),genesis,period,rate));
    }
    function setProcessor(address circuits,uint256 multiplier) external onlyOwner unsealed {require(multiplier<=100,'MULTIPLIER');processorMultiplier[circuits]=multiplier;}
    function setBoost(address boost_) external onlyOwner unsealed {boost=boost_;}
    function pause() external onlyOwner unsealed {_pause();}
    function unpause() external onlyOwner unsealed {_unpause();}
    function freezeTasks() external onlyOwner unsealed {registry.freezeTasks();}
    function taskCount() external view returns(uint32){return registry.taskCount();}
    function tasksFrozen() external view returns(bool){return registry.tasksFrozen();}
    function getTask(uint32 taskId) external view returns(ROtapTaskRegistry.Task memory){return registry.getTask(taskId);}
    function startTime() external view returns(uint256){return ledger.startTime();}
    function currentRate() external view returns(uint256){return ledger.currentRate();}
    function token() external view returns(address){return address(ledger.token());}
    function totalMined() external view returns(uint256){return ledger.token().totalSupply();}
    function totalForgone() external view returns(uint256){return ledger.totalForgone();}
    function totalVerifWeight() external view returns(uint256){return ledger.totalVerifWeight();}
    function totalUnverWeight() external view returns(uint256){return ledger.totalUnverWeight();}
    function accVerif() external view returns(uint256){return ledger.accVerif();}
    function accUnver() external view returns(uint256){return ledger.accUnver();}
    function lastUpdate() external view returns(uint256){return ledger.lastUpdate();}
    function pending(bytes32 key) external view returns(uint256){Miner storage m=miners[key];if(!m.active||m.revoked)return 0;uint256 factor=boost==address(0)?10000:IROtapFactor(boost).factorBps(m.holder);if(m.taskId==0)return ledger.pendingAtWeights(key,0,m.burn*m.mult*100);uint256 bonus=bestSlot[m.taskId][m.circuits]==key?registry.bonusOf(m.taskId,m.cost):0;return ledger.pendingAtWeights(key,(m.burn*factor+bonus*10000)*m.mult/100,0);}
    function poke() external {ledger.poke();}
    function addTask(string calldata name,uint8 kind,uint32 cycles,uint32 nIn,uint32 nOut,uint32 vectorCount,bytes32 root,address referenceCircuits,uint256 referenceId,uint256 anchor,bytes[] calldata inputs,bytes[] calldata expected,bytes32[][] calldata proofs) external onlyOwner returns(uint32){
        require(kind<=1&&anchor>0&&block.number>anchor&&block.number-anchor<=MAX_ANCHOR_AGE,'CONFIG');(uint32 actualIn,uint32 actualOut,uint32 states,)=IROtapMinerCircuit(referenceCircuits).circuitInfo(referenceId);require(actualIn==nIn&&actualOut==nOut&&(states>0)==(kind==1),'SHAPE');bytes memory program=IROtapMinerCircuit(referenceCircuits).netlist(referenceId);uint32 count=sampling.sampleCountFor(registry.liveGateCount(program,nIn,nOut),cycles);require(inputs.length==count,'SAMPLES');uint32[] memory indexes_=sampling.indexes(blockhash(anchor),referenceCircuits,referenceId,vectorCount,count);return registry.publish(name,referenceCircuits,referenceId,cycles,vectorCount,root,indexes_,inputs,expected,proofs);
    }
    function updateTaskRef(uint32 taskId,address circuits,uint256 id) external onlyOwner unsealed {registry.updateTaskRef(taskId,circuits,id);}
    function invalidateEligibilityCache() external onlyOwner unsealed {eligibleEpoch++;}
    function maxRunGas() external view returns(uint256){return IROtapSamplingAdmin(address(sampling)).maxRunGas();}
    function raiseMaxRunGas(uint256 limit) external onlyOwner unsealed {IROtapSamplingAdmin(address(sampling)).raiseMaxRunGas(limit);}
    function seal() external onlyOwner unsealed whenNotPaused {registry.freezeTasks();IROtapSamplingAdmin(address(sampling)).seal();isSealed=true;emit Sealed();}
    function _authorizeUpgrade(address) internal override onlyOwner unsealed {}
    function minerCount() external view returns(uint256){return allKeys.length;}
    function minerAt(uint256 index) external view returns(bytes32){return allKeys[index];}
    function holderMinerCount(address holder) external view returns(uint256){return holderKeys[holder].length;}
    function holderMinerAt(address holder,uint256 index) external view returns(bytes32){return holderKeys[holder][index];}
    function getMiner(bytes32 key) external view returns(Miner memory){return miners[key];}
    function ceCount(uint32 taskId,address circuits) external view returns(uint256){return counterexamples[taskId][circuits].length;}
    function counterexampleAt(uint32 taskId,address circuits,uint256 index) external view returns(bytes memory){return counterexamples[taskId][circuits][index];}
    function minerKey(address circuits,uint256 circuitId) public pure returns(bytes32){return keccak256(abi.encodePacked(circuits,circuitId));}
    function designCommitment(address designer,address circuits,bytes32 netlistHash,bytes32 salt) public pure returns(bytes32){return keccak256(abi.encode(designer,circuits,netlistHash,salt));}
    function commitDesign(address circuits,bytes32 commitment) external {require(processorMultiplier[circuits]>0&&commitment!=bytes32(0),'PROCESSOR');require(designCommits[circuits][commitment]==0,'DUPLICATE');designCommits[circuits][commitment]=block.number;designFirstUnusedId[circuits][commitment]=IROtapMinerCircuit(circuits).nextId()+1;}
    function arm(address circuits,uint256 id) external {require(IROtapMinerCircuit(circuits).ownerOf(id)==msg.sender&&processorMultiplier[circuits]>0,'OWNER');armedAt[minerKey(circuits,id)]=block.number;}
    function start(address circuits,uint256 id,uint32 taskId,uint256 anchor,bytes[] calldata inputs,bytes[] calldata expected,bytes32[][] calldata proofs,bytes32 salt) external whenNotPaused returns(bytes32 key){
        require(block.timestamp>=ledger.startTime()+OWNER_HEAD_START||msg.sender==owner(),'HEAD_START');
        require(processorMultiplier[circuits]>0&&IROtapMinerCircuit(circuits).ownerOf(id)==msg.sender,'OWNER');key=minerKey(circuits,id);Miner storage m=miners[key];
        require(!m.active&&!m.revoked&&block.number>=m.restartAt,'STATE');
        (uint32 nIn,uint32 nOut,,)=IROtapMinerCircuit(circuits).circuitInfo(id);
        ROtapRuntime.Metrics memory metrics=registry.inspectNetlist(IROtapMinerCircuit(circuits).netlist(id),nIn,nOut);require(metrics.burn>0,'BURN');
        if(taskId>0){
            require(armedAt[key]==anchor&&anchor>0&&block.number>anchor&&block.number-anchor<=MAX_ANCHOR_AGE&&blockhash(anchor)!=bytes32(0),'ANCHOR');
            ROtapTaskRegistry.Task memory task=registry.getTask(taskId);require(task.active,'CLOSED');uint32[] memory indexes=sampling.sampleIndexes(circuits,id,taskId,anchor);
            require(indexes.length>=3&&indexes.length<=task.vectorCount&&indexes.length==inputs.length&&inputs.length==expected.length&&inputs.length==proofs.length,'SAMPLES');
            require(sampling.checkBudget(metrics.nand+metrics.latch,task.cycles,indexes.length),'GAS_BUDGET');
            for(uint256 i;i<indexes.length;i++){
                require(registry.verifyOfficial(taskId,circuits,id,indexes[i],inputs[i],expected[i],proofs[i]),'VECTOR');
            }
        }
        if(m.circuits==address(0))allKeys.push(key);m.circuits=circuits;m.circuitId=id;m.taskId=taskId;m.active=true;m.cost=metrics.cost;m.burn=metrics.burn;m.holder=msg.sender;m.mult=processorMultiplier[circuits];
        bytes32 commitment=designCommitment(msg.sender,circuits,keccak256(IROtapMinerCircuit(circuits).netlist(id)),salt);uint256 committed=designCommits[circuits][commitment];
        if(committed>0&&id>=designFirstUnusedId[circuits][commitment]&&(m.designAt==0||committed<m.designAt))m.designAt=committed;
        attach(key,msg.sender);
        considerOriginal(key,false);
        sync(key,msg.sender);emit Started(key,msg.sender,taskId);
    }
    function sync(bytes32 key,address holder) private {
        Miner storage m=miners[key];uint256 verified;uint256 unverified;
        if(m.active&&!m.revoked){uint256 factor=boost==address(0)?10000:IROtapFactor(boost).factorBps(holder);uint256 multiplier=m.mult;
            if(m.taskId==0)unverified=m.burn*multiplier*100;
            else{uint256 bonus=bestSlot[m.taskId][m.circuits]==key?registry.bonusOf(m.taskId,m.cost):0;verified=(m.burn*factor+bonus*10000)*multiplier/100;}
        }
        ledger.setPosition(key,holder,verified,unverified);ledger.claimFor(holder,new bytes32[](0));
    }
    function considerOriginal(bytes32 key,bool mustImprove) private {
        Miner storage m=miners[key];bool qualified=m.active&&!m.revoked&&m.taskId>0&&m.designAt>0&&m.designAt<block.number&&passesCounterexamples(m.taskId,m.circuits,m.circuitId);bytes32 old=bestSlot[m.taskId][m.circuits];uint256 cost=bestCost[m.taskId][m.circuits];uint256 committed=bestCommitBlock[m.taskId][m.circuits];
        bool better=qualified&&old!=key&&(cost==0||m.cost<cost||(m.cost==cost&&old!=bytes32(0)&&m.designAt<committed));if(mustImprove)require(better,'WORSE');if(!better)return;
        bestSlot[m.taskId][m.circuits]=key;bestCost[m.taskId][m.circuits]=m.cost;bestCommitBlock[m.taskId][m.circuits]=m.designAt;if(old!=bytes32(0))sync(old,miners[old].holder);
    }
    function releaseOriginal(bytes32 key) private {Miner storage m=miners[key];if(bestSlot[m.taskId][m.circuits]==key)delete bestSlot[m.taskId][m.circuits];}
    function reclaim(bytes32 key) external whenNotPaused {considerOriginal(key,true);sync(key,miners[key].holder);}
    function stop(bytes32 key) external whenNotPaused {
        Miner storage m=miners[key];require(m.active&&IROtapMinerCircuit(m.circuits).ownerOf(m.circuitId)==msg.sender,'OWNER');
        m.active=false;m.restartAt=block.number+STOP_COOLDOWN;if(bestSlot[m.taskId][m.circuits]==key)bestTombstoneBlock[m.taskId][m.circuits]=block.number;sync(key,msg.sender);detach(key);emit Stopped(key);
    }
    function challenge(bytes32 key,uint32 index,bytes calldata input,bytes calldata expected,bytes32[] calldata proof) external whenNotPaused {
        Miner storage m=miners[key];require(m.active&&m.taskId>0,'MINER');require(!registry.verifyOfficial(m.taskId,m.circuits,m.circuitId,index,input,expected,proof),'PASSES');
        m.active=false;m.revoked=true;releaseOriginal(key);sync(key,m.holder);detach(key);emit Revoked(key,index);
    }
    function passesCounterexamples(uint32 taskId,address circuits,uint256 id) public view returns(bool){bytes[] storage examples=counterexamples[taskId][circuits];for(uint256 i;i<examples.length;i++)if(!registry.matchesReference(taskId,circuits,id,examples[i]))return false;return true;}
    function registerCounterexample(uint32 taskId,address circuits,bytes calldata input) external whenNotPaused {
        bytes32 key=bestSlot[taskId][circuits];require(key!=bytes32(0),'SLOT');Miner storage m=miners[key];require(!registry.matchesReference(taskId,circuits,m.circuitId,input),'PASSES');
        bytes[] storage examples=counterexamples[taskId][circuits];for(uint256 i;i<examples.length;i++)require(keccak256(examples[i])!=keccak256(input),'DUPLICATE');examples.push(input);
    }
    function kick(uint32 taskId,address circuits) external whenNotPaused {bytes32 key=bestSlot[taskId][circuits];require(key!=bytes32(0),'SLOT');Miner storage m=miners[key];require(!passesCounterexamples(taskId,circuits,m.circuitId),'PASSES');releaseOriginal(key);sync(key,m.holder);emit Demoted(key,'');}
    function claim(bytes32 key) external whenNotPaused returns(uint256){bytes32[] memory keys=new bytes32[](1);keys[0]=key;return claimKeys(keys);}
    function claimMany(bytes32[] calldata keys) external whenNotPaused returns(uint256){return claimKeys(keys);}
    function claimKeys(bytes32[] memory keys) private returns(uint256 amount){uint256 beforeSupply=ledger.token().totalSupply();for(uint256 i;i<keys.length;i++){Miner storage m=miners[keys[i]];require(m.circuits!=address(0),'MINER');sync(keys[i],m.holder);}return ledger.token().totalSupply()-beforeSupply;}
    function beforeCircuitTransfer(uint256 id,address from,address to) external {
        require(processorMultiplier[msg.sender]>0,'PROCESSOR');bytes32 key=minerKey(msg.sender,id);Miner storage m=miners[key];if(!m.active)return;require(m.holder==from,'HOLDER');
        detach(key);m.holder=to;attach(key,to);ledger.reassign(key,to);
    }
    function beforeFactorChange(address holder) external {require(msg.sender==boost,'BOOST');bytes32[] storage keys=holderKeys[holder];if(keys.length>0)require(!paused(),'PAUSED');ledger.claimFor(holder,keys);}
    function afterFactorChange(address holder) external {require(msg.sender==boost,'BOOST');bytes32[] storage keys=holderKeys[holder];for(uint256 i;i<keys.length;i++)sync(keys[i],holder);}
    function beforeFactorChangeForKeys(address,bytes32[] calldata keys) external {require(msg.sender==boost,'BOOST');if(keys.length>0)require(!paused(),'PAUSED');claimKeys(keys);}
    function afterFactorChangeForKeys(address,bytes32[] calldata keys) external {require(msg.sender==boost,'BOOST');if(keys.length>0)require(!paused(),'PAUSED');claimKeys(keys);}
    function attach(bytes32 key,address holder) private {holderIndex[key]=holderKeys[holder].length;holderKeys[holder].push(key);}
    function detach(bytes32 key) private {address holder=miners[key].holder;bytes32[] storage keys=holderKeys[holder];uint256 index=holderIndex[key];bytes32 last=keys[keys.length-1];keys[index]=last;holderIndex[last]=index;keys.pop();delete holderIndex[key];}
}

ROtapMarkets.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import '@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol';
import '@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol';
interface IROtap1155 {function safeTransferFrom(address,address,uint256,uint256,bytes calldata) external;function circuits() external view returns(address);}
interface IROtap721 {function ownerOf(uint256) external view returns(address);function transferFrom(address,address,uint256) external;function getApproved(uint256) external view returns(address);function isApprovedForAll(address,address) external view returns(bool);function factory() external view returns(address);function transistors() external view returns(address);}
interface IROtapMarketFactory {function isCPU(address) external view returns(bool);}

abstract contract ROtapFeeVault is OwnableUpgradeable,UUPSUpgradeable {
    uint16 public constant MAX_FEE_BPS=300;
    address public protocolWallet;address public factory;uint16 public feeBps;bool public isSealed;
    mapping(address=>bool) public externalFactories;mapping(address=>uint256) public owed;uint256 private entered;
    event FeeBpsSet(uint16 fee);event ProtocolWalletSet(address wallet);event ExternalFactorySet(address indexed origin,bool allowed);event Sealed();event Withdrawn(address indexed recipient,uint256 amount);
    modifier nonReentrant(){require(entered==0,'REENTRANCY');entered=1;_;entered=0;}
    constructor(address treasury,address factory_){_disableInitializers();if(treasury!=address(0)){require(factory_.code.length>0,'FACTORY');_transferOwnership(msg.sender);protocolWallet=treasury;factory=factory_;feeBps=100;}}
    function initialize(address owner_,address factory_,address treasury,uint16 fee) external initializer {require(factory_.code.length>0&&treasury!=address(0)&&fee<=MAX_FEE_BPS,'CONFIG');__Ownable_init(owner_);__UUPSUpgradeable_init();factory=factory_;protocolWallet=treasury;feeBps=fee;_initializeMarketState();}
    function _initializeMarketState() internal virtual {}
    function setFeeBps(uint16 fee) external onlyOwner {require(fee<=MAX_FEE_BPS,'FEE');feeBps=fee;emit FeeBpsSet(fee);}
    function setProtocolWallet(address wallet) external onlyOwner {require(wallet!=address(0),'ZERO');protocolWallet=wallet;emit ProtocolWalletSet(wallet);}
    function setExternalFactory(address origin,bool allowed) external onlyOwner {require(origin.code.length>0,'FACTORY');externalFactories[origin]=allowed;emit ExternalFactorySet(origin,allowed);}
    function validCircuit(address circuit) internal view returns(bool){if(circuit.code.length==0)return false;try IROtapMarketFactory(factory).isCPU(circuit) returns(bool registered){if(registered)return true;}catch{}try IROtap721(circuit).factory() returns(address origin){return externalFactories[origin]&&IROtapMarketFactory(origin).isCPU(circuit);}catch{return false;}}
    function validMaterial(address material) internal view returns(bool){if(material.code.length==0)return false;try IROtap1155(material).circuits() returns(address circuit){return validCircuit(circuit)&&IROtap721(circuit).transistors()==material;}catch{return false;}}
    function saleCredit(address seller,uint256 gross,uint16 rate) internal {uint256 fee=gross*rate/10000;owed[protocolWallet]+=fee;uint256 proceeds=gross-fee;(bool ok,)=payable(seller).call{value:proceeds}('');require(ok,'TRANSFER');}
    function withdraw() external nonReentrant {uint256 amount=owed[msg.sender];require(amount>0,'NOTHING');owed[msg.sender]=0;(bool ok,)=payable(msg.sender).call{value:amount}('');require(ok,'TRANSFER');emit Withdrawn(msg.sender,amount);}
    function seal() external onlyOwner {isSealed=true;_transferOwnership(address(0));emit Sealed();}
    function _authorizeUpgrade(address) internal override onlyOwner {require(!isSealed,'SEALED');}
}

contract ROtapTransistorMarket is ROtapFeeVault {
    struct Order {address maker;address transistors;uint96 price;uint8 tokenId;uint16 feeBps;uint256 remaining;}
    uint256 public nextAskId;uint256 public nextBidId;
    mapping(uint256=>Order) public asks;mapping(uint256=>Order) public bids;
    event AskPlaced(uint256 indexed orderId,address indexed maker,address indexed transistors,uint8 tokenId,uint96 price,uint256 quantity);
    event BidPlaced(uint256 indexed orderId,address indexed maker,address indexed transistors,uint8 tokenId,uint96 price,uint256 quantity);
    event Filled(bool indexed ask,uint256 indexed orderId,address indexed taker,uint256 amount);event Cancelled(bool indexed ask,uint256 indexed orderId);
    constructor(address treasury,address factory_) ROtapFeeVault(treasury,factory_){}
    function _initializeMarketState() internal override {}
    function askRemaining(uint256 id) external view returns(uint256){return asks[id].remaining;}
    function bidRemaining(uint256 id) external view returns(uint256){return bids[id].remaining;}
    function placeAsk(address material,uint8 id,uint96 price,uint256 amount) external nonReentrant returns(uint256 orderId){require(validMaterial(material)&&id<2&&amount>0&&price>0,'ORDER');orderId=++nextAskId;asks[orderId]=Order(msg.sender,material,price,id,feeBps,amount);IROtap1155(material).safeTransferFrom(msg.sender,address(this),id,amount,'');emit AskPlaced(orderId,msg.sender,material,id,price,amount);}
    function placeBid(address material,uint8 id,uint96 price,uint256 amount) external payable nonReentrant returns(uint256 orderId){require(validMaterial(material)&&id<2&&amount>0&&price>0&&msg.value==amount*price,'ORDER');orderId=++nextBidId;bids[orderId]=Order(msg.sender,material,price,id,feeBps,amount);emit BidPlaced(orderId,msg.sender,material,id,price,amount);}
    function fillAsk(uint256 id,uint256 amount) external payable nonReentrant {Order storage order=asks[id];require(amount>0&&amount<=order.remaining,'ORDER');uint256 gross=amount*order.price;require(msg.value==gross,'PAYMENT');order.remaining-=amount;saleCredit(order.maker,gross,order.feeBps);IROtap1155(order.transistors).safeTransferFrom(address(this),msg.sender,order.tokenId,amount,'');emit Filled(true,id,msg.sender,amount);}
    function fillBid(uint256 id,uint256 amount) external nonReentrant {Order storage order=bids[id];require(amount>0&&amount<=order.remaining,'ORDER');order.remaining-=amount;saleCredit(msg.sender,amount*order.price,order.feeBps);IROtap1155(order.transistors).safeTransferFrom(msg.sender,order.maker,order.tokenId,amount,'');emit Filled(false,id,msg.sender,amount);}
    function cancelAsk(uint256 id) external nonReentrant {Order storage order=asks[id];require(order.maker==msg.sender&&order.remaining>0,'AUTH');uint256 quantity=order.remaining;order.remaining=0;IROtap1155(order.transistors).safeTransferFrom(address(this),msg.sender,order.tokenId,quantity,'');emit Cancelled(true,id);}
    function cancelBid(uint256 id) external nonReentrant {Order storage order=bids[id];require(order.maker==msg.sender&&order.remaining>0,'AUTH');uint256 refund=order.remaining*order.price;order.remaining=0;(bool ok,)=payable(msg.sender).call{value:refund}('');require(ok,'REFUND');emit Cancelled(false,id);}
    function onERC1155Received(address,address,uint256,uint256,bytes calldata) external view returns(bytes4){require(validMaterial(msg.sender),'TOKEN');return 0xf23a6e61;}
    function onERC1155BatchReceived(address,address,uint256[] calldata,uint256[] calldata,bytes calldata) external pure returns(bytes4){return 0xbc197c81;}
    function supportsInterface(bytes4 interfaceId) external pure returns(bool){return interfaceId==0x01ffc9a7||interfaceId==0x4e2312e0;}
}

contract ROtapCircuitMarket is ROtapFeeVault {
    struct Listing {address seller;address circuits;uint96 price;uint16 feeBps;uint256 tokenId;bool active;}
    uint256 public nextListingId;mapping(uint256=>Listing) private items;mapping(address=>mapping(uint256=>uint256)) public listingOf;
    event Listed(uint256 indexed listingId,address indexed seller,address indexed circuits,uint256 tokenId,uint96 price);event Bought(uint256 indexed listingId,address indexed buyer);event Delisted(uint256 indexed listingId);
    constructor(address treasury,address factory_) ROtapFeeVault(treasury,factory_){}
    function _initializeMarketState() internal override {}
    function listings(uint256 id) external view returns(address seller,address circuits,uint96 price,uint16 fee,uint256 tokenId){Listing storage item=items[id];return(item.seller,item.circuits,item.price,item.feeBps,item.tokenId);}
    function listingView(uint256 id) public view returns(address seller,address circuits,uint256 tokenId,uint96 price,uint16 fee,bool active){Listing storage item=items[id];return(item.seller,item.circuits,item.tokenId,item.price,item.feeBps,item.active);}
    function listingFor(address circuit,uint256 tokenId) external view returns(uint256 id,address seller,uint96 price,bool active){id=listingOf[circuit][tokenId];Listing storage item=items[id];return(id,item.seller,item.price,item.active);}
    function list(address circuit,uint256 tokenId,uint96 price) external nonReentrant returns(uint256 id){require(validCircuit(circuit)&&price>0&&IROtap721(circuit).ownerOf(tokenId)==msg.sender,'OWNER');require(IROtap721(circuit).getApproved(tokenId)==address(this)||IROtap721(circuit).isApprovedForAll(msg.sender,address(this)),'APPROVAL');uint256 old=listingOf[circuit][tokenId];if(old!=0)items[old].active=false;id=++nextListingId;items[id]=Listing(msg.sender,circuit,price,feeBps,tokenId,true);listingOf[circuit][tokenId]=id;emit Listed(id,msg.sender,circuit,tokenId,price);}
    function setPrice(uint256 id,uint96 price) external {Listing storage item=items[id];require(item.active&&item.seller==msg.sender&&price>0,'AUTH');item.price=price;}
    function deactivate(uint256 id) private {Listing storage item=items[id];item.active=false;delete listingOf[item.circuits][item.tokenId];emit Delisted(id);}
    function delist(uint256 id) external {Listing storage item=items[id];require(item.active&&item.seller==msg.sender,'AUTH');deactivate(id);}
    function delistStale(uint256 id) external {Listing storage item=items[id];IROtap721 circuit=IROtap721(item.circuits);require(item.active&&(circuit.ownerOf(item.tokenId)!=item.seller||(circuit.getApproved(item.tokenId)!=address(this)&&!circuit.isApprovedForAll(item.seller,address(this)))),'CURRENT');deactivate(id);}
    function buy(uint256 id,uint96 expectedPrice) external payable nonReentrant {Listing storage item=items[id];require(item.active&&item.price==expectedPrice&&msg.value==item.price&&IROtap721(item.circuits).ownerOf(item.tokenId)==item.seller,'LISTING');item.active=false;delete listingOf[item.circuits][item.tokenId];saleCredit(item.seller,item.price,item.feeBps);IROtap721(item.circuits).transferFrom(item.seller,msg.sender,item.tokenId);emit Bought(id,msg.sender);}
}

